1	// Acceptance test for the change request:
2	//   "Let me filter my projects by label."
3	//
4	// The projects list page (projects-page, /projects), which lists every project, gains a control
5	// (data-testid="project-tag-filter") that narrows the one list down to the projects carrying a
6	// SINGLE chosen label. Labels are DATA — the tags seeded onto projects (the same labels the project
7	// detail page shows as chips, grouped via projectTags) — so the filter's options are those labels,
8	// not a fixed set of stages. Choosing a label leaves only the projects that carry it; a project that
9	// does not carry the chosen label (including one carrying no labels at all) drops out. Before a label
10	// is chosen the list is unfiltered (every project shows). Choosing a DIFFERENT label narrows to THAT
11	// label's projects, and returning to "all labels" brings every project back — so the filter is
12	// genuinely keyed on the chosen label and not hardwired to one. Because a filter outlives a click
13	// (CLAUDE.md rule 4) the chosen label lives in the URL and survives a fresh load. Filtering is a pure
14	// view concern: it records nothing.
15	//
16	// The contract for the control mirrors its toolbar siblings (invoice-status-filter / task-filter): it
17	// is a <select> in the projects toolbar with one option per label (its label text NAMING the label)
18	// plus a default "all labels" option carrying an empty value (no label => unfiltered). The test
19	// chooses a label by finding the option whose text NAMES that label (case-insensitively) and
20	// selecting it by the option's OWN value, so it binds to the label's MEANING — not the exact value
21	// (tag id or tag name) the control uses internally.
22	//
23	// Asserts ONLY through the two public channels: the UI (data-testid) and the audit file
24	// (auditLines()). Data is arranged via resetAndSeed (the app's /__test__ endpoint): `clients`
25	// honours { id, name, email }, `projects` honours { id, name, clientId, archived }, `tags` honours
26	// { id, name } and `projectTags` (the join putting a label on a project) honours { projectId, tagId }.
27	import { test, expect, type Page, type Locator } from '@playwright/test';
28	import { resetAndSeed } from '../support/seed';
29	import { auditLines } from '../support/audit';
30	
31	// Each label matched by the WORD that names it, case-insensitively, so the test binds to the MEANING
32	// and not one capitalisation. Word boundaries keep the labels distinct; none of these words is a
33	// substring of another, nor of the default "all labels" option text.
34	const URGENT = /\burgent\b/i;
35	const BACKEND = /\bbackend\b/i;
36	const RESEARCH = /\bresearch\b/i;
37	
38	const projectRows = (page: Page) => page.locator('[data-testid^="project-row-"]');
39	
40	// Projects spread across three labels, several projects per label so narrowing to one label must drop
41	// several rows — a filter that merely hid a single row, or one hardwired to one label, could not
42	// reproduce these results. One project carries NO label at all, so it must disappear under every label
43	// and reappear only under "all labels". All projects are left un-archived so the sibling show-archived
44	// toggle plays no part here. Project names are chosen so none contains a label word (keeping the two
45	// concerns independent).
46	const SEED = {
47	  clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
48	  projects: [
49	    { id: 1, name: 'Website Rebuild', clientId: 1 },
50	    { id: 2, name: 'Mobile App', clientId: 1 },
51	    { id: 3, name: 'Billing System', clientId: 1 },
52	    { id: 4, name: 'Internal Portal', clientId: 1 },
53	    { id: 5, name: 'Marketing Hub', clientId: 1 },
54	  ],
55	  tags: [
56	    { id: 1, name: 'urgent' },
57	    { id: 2, name: 'backend' },
58	    { id: 3, name: 'research' },
59	  ],
60	  projectTags: [
61	    // urgent → projects 1 and 2
62	    { projectId: 1, tagId: 1 },
63	    { projectId: 2, tagId: 1 },
64	    // backend → projects 3 and 4
65	    { projectId: 3, tagId: 2 },
66	    { projectId: 4, tagId: 2 },
67	    // research → project 1 (project 1 carries two labels)
68	    { projectId: 1, tagId: 3 },
69	    // project 5 carries no label at all
70	  ],
71	};
72	
73	const URGENT_IDS = [1, 2];
74	const BACKEND_IDS = [3, 4];
75	const RESEARCH_IDS = [1];
76	const ALL_IDS = [1, 2, 3, 4, 5];
77	
78	// The ids of the currently-rendered project rows, ascending (order is not what this feature is about).
79	async function visibleIds(page: Page): Promise<number[]> {
80	  return projectRows(page).evaluateAll((els) =>
81	    els
82	      .map((el) => Number(el.getAttribute('data-testid')!.replace('project-row-', '')))
83	      .sort((a, b) => a - b),
84	  );
85	}
86	
87	// Choose a label in the filter. The option is found by the label WORD in its text and selected by that
88	// option's own value, so the label is pinned by meaning, not by an exact value/capitalisation.
89	async function chooseLabel(page: Page, word: RegExp): Promise<void> {
90	  const filter = page.getByTestId('project-tag-filter');
91	  await expect(filter).toBeVisible();
92	  const value = await filter
93	    .locator('option')
94	    .filter({ hasText: word })
95	    .first()
96	    .evaluate((el: HTMLOptionElement) => el.value);
